PRAGMA foreign_keys=OFF;
CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "username" TEXT NOT NULL, "mobile" TEXT, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL, "roleKey" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE UNIQUE INDEX "User_mobile_key" ON "User"("mobile");
CREATE TABLE "Session" ("id" TEXT NOT NULL PRIMARY KEY, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Request" ("id" TEXT NOT NULL PRIMARY KEY, "project" TEXT NOT NULL, "supplier" TEXT NOT NULL, "invoice" TEXT, "requestNumber" TEXT NOT NULL, "date" DATETIME NOT NULL, "department" TEXT NOT NULL, "purchaseType" TEXT NOT NULL, "description" TEXT, "amount" INTEGER NOT NULL, "status" TEXT NOT NULL, "statusType" TEXT NOT NULL, "priority" TEXT NOT NULL DEFAULT 'NORMAL', "createdById" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Request_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Request_requestNumber_key" ON "Request"("requestNumber"); CREATE INDEX "Request_status_idx" ON "Request"("status"); CREATE INDEX "Request_createdById_idx" ON "Request"("createdById"); CREATE INDEX "Request_date_idx" ON "Request"("date");
CREATE TABLE "RequestItem" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "requestId" TEXT NOT NULL, "title" TEXT NOT NULL, "quantity" INTEGER NOT NULL, "unitPrice" INTEGER NOT NULL, "total" INTEGER NOT NULL, "description" TEXT, CONSTRAINT "RequestItem_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "Request" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Approval" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "requestId" TEXT NOT NULL, "userId" TEXT NOT NULL, "roleKey" TEXT NOT NULL, "action" TEXT NOT NULL, "status" TEXT NOT NULL, "description" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Approval_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "Request" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Approval_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Approval_requestId_createdAt_idx" ON "Approval"("requestId", "createdAt");
CREATE TABLE "Payment" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "requestId" TEXT NOT NULL, "amount" INTEGER NOT NULL, "paidAmount" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, "paidAt" DATETIME, "receiptName" TEXT, "receiptSize" TEXT, "verifiedAt" DATETIME, "verifiedById" TEXT, CONSTRAINT "Payment_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "Request" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Payment_verifiedById_fkey" FOREIGN KEY ("verifiedById") REFERENCES "User" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Payment_requestId_key" ON "Payment"("requestId");
CREATE TABLE "Activity" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "requestId" TEXT, "action" TEXT NOT NULL, "description" TEXT NOT NULL, "type" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Activity_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "Activity_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "Request" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "Activity_createdAt_idx" ON "Activity"("createdAt"); CREATE INDEX "Activity_type_idx" ON "Activity"("type");
CREATE TABLE "Task" ("id" TEXT NOT NULL PRIMARY KEY, "requestId" TEXT NOT NULL, "assigneeId" TEXT NOT NULL, "title" TEXT NOT NULL, "stage" TEXT NOT NULL, "stageType" TEXT NOT NULL, "action" TEXT NOT NULL, "dueAt" DATETIME, "completed" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Task_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "Request" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "Task_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Task_assigneeId_completed_idx" ON "Task"("assigneeId", "completed");
CREATE TABLE "UserSetting" ("userId" TEXT NOT NULL PRIMARY KEY, "theme" TEXT NOT NULL DEFAULT 'light', "taskAssigned" BOOLEAN NOT NULL DEFAULT true, "requestUpdates" BOOLEAN NOT NULL DEFAULT true, "paymentUpdates" BOOLEAN NOT NULL DEFAULT true, "systemActivities" BOOLEAN NOT NULL DEFAULT false, CONSTRAINT "UserSetting_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
PRAGMA foreign_keys=ON;
